package com.prueba.orderms.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "orders")
public class Order {

    @Id
    private UUID id;

    @Column(name = "customer_name", nullable = false)
    private String customerName;

    @Column(name = "customer_email", nullable = false)
    private String customerEmail;

    @Column(name = "product_sku", nullable = false)
    private String productSku;

    @Column(name = "product_name", nullable = false)
    private String productName;

    @Column(nullable = false)
    private Integer quantity;

    @Column(name = "unit_price", nullable = false)
    private BigDecimal unitPrice;

    @Column(name = "total_amount", nullable = false)
    private BigDecimal totalAmount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private OrderStatus status;

    @Column(name = "card_holder", nullable = false)
    private String cardHolder;

    @Column(name = "card_brand", nullable = false)
    private String cardBrand;

    @Column(name = "card_last_four", nullable = false, length = 4)
    private String cardLastFour;

    @Column(name = "encrypted_card_payload", nullable = false, columnDefinition = "TEXT")
    private String encryptedCardPayload;

    @Column(name = "payment_reference")
    private String paymentReference;

    @Column(name = "failure_reason")
    private String failureReason;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    private Long version;

    protected Order() {
        // Requerido por JPA
    }

    public static Order nuevo(String customerName, String customerEmail,
                              String productSku, String productName,
                              int quantity, BigDecimal unitPrice, String currency,
                              String cardHolder, String cardBrand, String cardLastFour,
                              String encryptedCardPayload) {
        Order pedido = new Order();
        pedido.id = UUID.randomUUID();
        pedido.customerName = customerName;
        pedido.customerEmail = customerEmail;
        pedido.productSku = productSku;
        pedido.productName = productName;
        pedido.quantity = quantity;
        pedido.unitPrice = unitPrice;
        pedido.totalAmount = unitPrice.multiply(BigDecimal.valueOf(quantity))
                .setScale(2, RoundingMode.HALF_UP);
        pedido.currency = currency;
        pedido.status = OrderStatus.PENDIENTE;
        pedido.cardHolder = cardHolder;
        pedido.cardBrand = cardBrand;
        pedido.cardLastFour = cardLastFour;
        pedido.encryptedCardPayload = encryptedCardPayload;
        pedido.createdAt = Instant.now();
        pedido.updatedAt = pedido.createdAt;
        return pedido;
    }

    public void marcarPagado(String referenciaDePago) {
        exigirPendiente();
        this.status = OrderStatus.PAGADO;
        this.paymentReference = referenciaDePago;
        this.updatedAt = Instant.now();
    }

    public void marcarFallido(String motivo) {
        exigirPendiente();
        this.status = OrderStatus.FALLO_PAGO;
        this.failureReason = motivo;
        this.updatedAt = Instant.now();
    }

    public boolean estaPendiente() {
        return status == OrderStatus.PENDIENTE;
    }

    private void exigirPendiente() {
        if (status != OrderStatus.PENDIENTE) {
            throw new IllegalStateException(
                    "El pedido %s ya se encuentra en estado %s".formatted(id, status));
        }
    }

    public UUID getId() { return id; }
    public String getCustomerName() { return customerName; }
    public String getCustomerEmail() { return customerEmail; }
    public String getProductSku() { return productSku; }
    public String getProductName() { return productName; }
    public Integer getQuantity() { return quantity; }
    public BigDecimal getUnitPrice() { return unitPrice; }
    public BigDecimal getTotalAmount() { return totalAmount; }
    public String getCurrency() { return currency; }
    public OrderStatus getStatus() { return status; }
    public String getCardHolder() { return cardHolder; }
    public String getCardBrand() { return cardBrand; }
    public String getCardLastFour() { return cardLastFour; }
    public String getEncryptedCardPayload() { return encryptedCardPayload; }
    public String getPaymentReference() { return paymentReference; }
    public String getFailureReason() { return failureReason; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}

package com.prueba.orderms.web;

import com.prueba.orderms.domain.OrderStatus;
import com.prueba.orderms.service.OrderService;
import com.prueba.orderms.web.dto.CreateOrderRequest;
import com.prueba.orderms.web.dto.OrderResponse;
import com.prueba.orderms.web.dto.PagedResponse;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import java.net.URI;
import java.util.UUID;

@RestController
@RequestMapping("/api/v1/orders")
@Tag(name = "Pedidos", description = "Creacion y consulta de pedidos")
public class OrderController {

    private final OrderService servicio;

    public OrderController(OrderService servicio) {
        this.servicio = servicio;
    }

    @PostMapping
    @Operation(summary = "Crear un pedido",
            description = "Los datos de tarjeta deben llegar cifrados con la llave publica "
                    + "que expone /api/v1/crypto/public-key.")
    public ResponseEntity<OrderResponse> crear(@Valid @RequestBody CreateOrderRequest solicitud,
                                               UriComponentsBuilder constructorDeUri) {
        OrderResponse respuesta = OrderResponse.desde(servicio.crear(solicitud));
        URI ubicacion = constructorDeUri.path("/api/v1/orders/{id}")
                .buildAndExpand(respuesta.id())
                .toUri();
        return ResponseEntity.created(ubicacion).body(respuesta);
    }

    @GetMapping("/{id}")
    @Operation(summary = "Consultar un pedido por su identificador")
    public OrderResponse porId(@PathVariable UUID id) {
        return OrderResponse.desde(servicio.buscarPorId(id));
    }

    @GetMapping
    @Operation(summary = "Listar pedidos",
            description = "Ordenados por fecha de creacion descendente. "
                    + "El parametro status permite filtrar por estado.")
    public PagedResponse<OrderResponse> listar(
            @RequestParam(required = false) OrderStatus status,
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size) {

        int tamanoAcotado = Math.min(Math.max(size, 1), 100);
        PageRequest paginacion = PageRequest.of(
                Math.max(page, 0), tamanoAcotado, Sort.by(Sort.Direction.DESC, "createdAt"));

        return PagedResponse.desde(servicio.listar(status, paginacion), OrderResponse::desde);
    }
}

